import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    return {"x": torch.rand(shape, dtype=dtype, device=device)}


def run(x):
    return torch.log10_(x)


def run_correctness(x):
    result = torch.log10(x.float()).to(x.dtype)
    x.copy_(result)
    return x
